def count_exact_distinct(nums: list[int], k: int) -> int:
    def at_most(limit: int) -> int:      # subarrays with at most `limit` distinct values
        count = {}
        left = total = 0
        for right, x in enumerate(nums):
            count[x] = count.get(x, 0) + 1
            while len(count) > limit:
                y = nums[left]
                count[y] -= 1
                if count[y] == 0:
                    del count[y]
                left += 1
            total += right - left + 1    # every start from left to right is valid
        return total

    return at_most(k) - at_most(k - 1)

perf.naive:
def count_exact_distinct(nums: list[int], k: int) -> int:
    total = 0
    for i in range(len(nums)):
        seen = set()
        for j in range(i, len(nums)):
            seen.add(nums[j])
            if len(seen) > k:
                break
            if len(seen) == k:
                total += 1
    return total
